-- The Broken Oath: compact beta chapter. Generated by tools/content/build_beta.php.
-- Requires current schema through v30_80. Back up the VPS database before import.
-- Uses existing SWFs only. Quest progress slot 90 is reserved for this pack.
CREATE TABLE IF NOT EXISTS aera_content_packs (Name varchar(64) PRIMARY KEY, InstalledAt timestamp DEFAULT CURRENT_TIMESTAMP);
DELIMITER $$
DROP PROCEDURE IF EXISTS install_broken_oath$$
CREATE PROCEDURE install_broken_oath()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 SET @entryMap=(SELECT id FROM maps WHERE Name='newbie' LIMIT 1);
 IF @entryMap IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing newbie entry map'; END IF;
 IF NOT EXISTS (SELECT 1 FROM aera_content_packs WHERE Name='broken-oath-beta') THEN
 IF EXISTS (SELECT 1 FROM `maps` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in maps'; END IF;
 IF EXISTS (SELECT 1 FROM `items` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in items'; END IF;
 IF EXISTS (SELECT 1 FROM `monsters` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in monsters'; END IF;
 IF EXISTS (SELECT 1 FROM `shops` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in shops'; END IF;
 IF EXISTS (SELECT 1 FROM `npcs` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in npcs'; END IF;
 IF EXISTS (SELECT 1 FROM `quests` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in quests'; END IF;
 IF EXISTS (SELECT 1 FROM `classes` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in classes'; END IF;
 IF EXISTS (SELECT 1 FROM `skills` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in skills'; END IF;
 IF EXISTS (SELECT 1 FROM `maps_npc` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in maps_npc'; END IF;
 IF EXISTS (SELECT 1 FROM `maps_monsters` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in maps_monsters'; END IF;
 IF EXISTS (SELECT 1 FROM `npcs_buttons` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in npcs_buttons'; END IF;
 IF EXISTS (SELECT 1 FROM `shops_items` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in shops_items'; END IF;
 IF EXISTS (SELECT 1 FROM `monsters_drops` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in monsters_drops'; END IF;
 IF EXISTS (SELECT 1 FROM `quests_requirements` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in quests_requirements'; END IF;
 IF EXISTS (SELECT 1 FROM `skills_assign` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in skills_assign'; END IF;
 IF EXISTS (SELECT 1 FROM `quests_rewards` WHERE id BETWEEN 810000 AND 810199) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Reserved content IDs occupied in quests_rewards'; END IF;
 IF EXISTS (SELECT 1 FROM quests WHERE Slot=90) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Quest slot 90 already used'; END IF;
 END IF;
 START TRANSACTION;
 COMMIT;
END$$
CALL install_broken_oath()$$
DROP PROCEDURE install_broken_oath$$
DELIMITER ;
