 INSERT INTO `npcs` (`id`,`Name`,`Gender`,`Job`,`Slogan`,`Level`,`Health`,`Mana`,`DPS`,`ColorHair`,`ColorSkin`,`ColorEye`,`ColorBase`,`ColorTrim`,`ColorAccessory`,`WeaponID`,`ArmorID`) VALUES (810001,'Scout Elowen','F','Briar Scout','The forest roots are freezing from within. Recover tainted sap, then break the rootwarden holding the northern road.',10,1000,100,0,'0x483329','0xD6AD8D','0x68B6C7','0x374F46','0xB6A276','0x688C99',810002,810001) ON DUPLICATE KEY UPDATE `Name`=VALUES(`Name`),`Gender`=VALUES(`Gender`),`Job`=VALUES(`Job`),`Slogan`=VALUES(`Slogan`),`Level`=VALUES(`Level`),`Health`=VALUES(`Health`),`Mana`=VALUES(`Mana`),`DPS`=VALUES(`DPS`),`ColorHair`=VALUES(`ColorHair`),`ColorSkin`=VALUES(`ColorSkin`),`ColorEye`=VALUES(`ColorEye`),`ColorBase`=VALUES(`ColorBase`),`ColorTrim`=VALUES(`ColorTrim`),`ColorAccessory`=VALUES(`ColorAccessory`),`WeaponID`=VALUES(`WeaponID`),`ArmorID`=VALUES(`ArmorID`);
 INSERT INTO `npcs` (`id`,`Name`,`Gender`,`Job`,`Slogan`,`Level`,`Health`,`Mana`,`DPS`,`ColorHair`,`ColorSkin`,`ColorEye`,`ColorBase`,`ColorTrim`,`ColorAccessory`,`WeaponID`,`ArmorID`) VALUES (810002,'Ranger Soren','M','Pass Keeper','The cold is being drawn toward the old ruins. Free the pass from its hollow sentries and defeat the queen bound to the signal.',10,1000,100,0,'0x483329','0xD6AD8D','0x68B6C7','0x374F46','0xB6A276','0x688C99',810012,810011) ON DUPLICATE KEY UPDATE `Name`=VALUES(`Name`),`Gender`=VALUES(`Gender`),`Job`=VALUES(`Job`),`Slogan`=VALUES(`Slogan`),`Level`=VALUES(`Level`),`Health`=VALUES(`Health`),`Mana`=VALUES(`Mana`),`DPS`=VALUES(`DPS`),`ColorHair`=VALUES(`ColorHair`),`ColorSkin`=VALUES(`ColorSkin`),`ColorEye`=VALUES(`ColorEye`),`ColorBase`=VALUES(`ColorBase`),`ColorTrim`=VALUES(`ColorTrim`),`ColorAccessory`=VALUES(`ColorAccessory`),`WeaponID`=VALUES(`WeaponID`),`ArmorID`=VALUES(`ArmorID`);
 INSERT INTO `npcs` (`id`,`Name`,`Gender`,`Job`,`Slogan`,`Level`,`Health`,`Mana`,`DPS`,`ColorHair`,`ColorSkin`,`ColorEye`,`ColorBase`,`ColorTrim`,`ColorAccessory`,`WeaponID`,`ArmorID`) VALUES (810003,'Warden Ilyra','F','Oath Archivist','A lich has inverted the old ward. Silence its stone sentinels, reclaim the keystone, and restore the oath that protected these lands.',10,1000,100,0,'0x483329','0xD6AD8D','0x68B6C7','0x374F46','0xB6A276','0x688C99',810022,810021) ON DUPLICATE KEY UPDATE `Name`=VALUES(`Name`),`Gender`=VALUES(`Gender`),`Job`=VALUES(`Job`),`Slogan`=VALUES(`Slogan`),`Level`=VALUES(`Level`),`Health`=VALUES(`Health`),`Mana`=VALUES(`Mana`),`DPS`=VALUES(`DPS`),`ColorHair`=VALUES(`ColorHair`),`ColorSkin`=VALUES(`ColorSkin`),`ColorEye`=VALUES(`ColorEye`),`ColorBase`=VALUES(`ColorBase`),`ColorTrim`=VALUES(`ColorTrim`),`ColorAccessory`=VALUES(`ColorAccessory`),`WeaponID`=VALUES(`WeaponID`),`ArmorID`=VALUES(`ArmorID`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810001,1,'Sap Beneath the Frost','Defeat 4 Blighted Dire Wolves on the Briarwatch trails and collect their tainted sap. The wolves have been feeding on frozen roots.','This sap carries the old ward mark. The rootwarden has been turned into a conduit.',500,400,0,100,'S',1,0,1,90,1,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810002,1,'Break the Rootbound Seal','Defeat the Frozen Rootwarden at the end of Briarwatch and bring back its frostbound heart.','The road is open. My travel button leads to Winterpass; Ranger Soren will follow the ward signal with you.',800,650,0,100,'S',1,0,1,90,2,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810003,1,'Voices in the Snow','Collect 4 Hollow Echoes from Hollow Frost Wisps in Winterpass. Each carries part of the signal controlling the queen.','These are stolen memories, not winter spirits. The queen is another prisoner of the ward.',1100,900,0,100,'S',1,0,1,90,3,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810004,1,'Release the Winter Queen','Defeat the Bound Winter Queen at the summit and recover the northern ward fragment.','The queen is free. Take the road to Oath Ruins and find Warden Ilyra. She knows who broke the ward.',1400,1150,0,100,'S',1,0,1,90,4,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810005,1,'The Oath Remembers','Recover 4 Oathstone Fragments from Oathstone Sentinels in the ruins. We must rebuild the seal before confronting the lich.','The inscription names the thief: a lich feeding on the forest and the pass. Its stolen keystone is the final piece.',1700,1400,0,100,'S',1,0,1,90,5,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `quests` (`id`,`FactionID`,`Name`,`Description`,`EndText`,`Experience`,`Gold`,`Coins`,`ClassPoints`,`RewardType`,`Level`,`Upgrade`,`Once`,`Slot`,`Value`,`Field`,`Index`) VALUES (810006,1,'A Promise Restored','Defeat the Lich of the Broken Oath in the final chamber and recover the stolen keystone.','The keystone is restored. Spring can return to Briarwatch, and the pass is safe. You have earned the Oath Warden discipline. Return to Briarwatch through my travel button.',2000,1650,0,100,'S',1,0,1,90,6,'',-1) ON DUPLICATE KEY UPDATE `FactionID`=VALUES(`FactionID`),`Name`=VALUES(`Name`),`Description`=VALUES(`Description`),`EndText`=VALUES(`EndText`),`Experience`=VALUES(`Experience`),`Gold`=VALUES(`Gold`),`Coins`=VALUES(`Coins`),`ClassPoints`=VALUES(`ClassPoints`),`RewardType`=VALUES(`RewardType`),`Level`=VALUES(`Level`),`Upgrade`=VALUES(`Upgrade`),`Once`=VALUES(`Once`),`Slot`=VALUES(`Slot`),`Value`=VALUES(`Value`),`Field`=VALUES(`Field`),`Index`=VALUES(`Index`);
 INSERT INTO `classes` (`id`,`ItemID`,`Category`,`Description`,`ManaRegenerationMethods`,`StatsDescription`) VALUES (810051,810051,'M1','Winterpass Ranger uses physical attacks to reclaim the Broken Oath lands.','Gain mana by striking enemies and taking hits.','Strength improves damage; Endurance improves survival.') ON DUPLICATE KEY UPDATE `ItemID`=VALUES(`ItemID`),`Category`=VALUES(`Category`),`Description`=VALUES(`Description`),`ManaRegenerationMethods`=VALUES(`ManaRegenerationMethods`),`StatsDescription`=VALUES(`StatsDescription`);
